#include "polyphase_float_mpfr.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(c) do { if(!(c)){fprintf(stderr,"FAIL %s:%d: %s\n",__FILE__,__LINE__,#c);exit(1);} } while(0)
typedef int(*pfu)(ppf_t*,const ppf_t*,ppf_rnd_t,ppf_context_t*); typedef int(*mfu)(mpfr_ptr,mpfr_srcptr,mpfr_rnd_t);
typedef int(*pfuu)(ppf_t*,const ppf_t*,unsigned long,ppf_rnd_t,ppf_context_t*); typedef int(*mfuu)(mpfr_ptr,mpfr_srcptr,unsigned long,mpfr_rnd_t);
typedef int(*pfb)(ppf_t*,const ppf_t*,const ppf_t*,ppf_rnd_t,ppf_context_t*); typedef int(*mfb)(mpfr_ptr,mpfr_srcptr,mpfr_srcptr,mpfr_rnd_t);
typedef int(*pfbu)(ppf_t*,const ppf_t*,const ppf_t*,unsigned long,ppf_rnd_t,ppf_context_t*); typedef int(*mfbu)(mpfr_ptr,mpfr_srcptr,mpfr_srcptr,unsigned long,mpfr_rnd_t);
static const ppf_rnd_t pr[5]={PPF_RNDN,PPF_RNDZ,PPF_RNDU,PPF_RNDD,PPF_RNDA};static const mpfr_rnd_t mr[5]={MPFR_RNDN,MPFR_RNDZ,MPFR_RNDU,MPFR_RNDD,MPFR_RNDA};
static int sg(int x){return(x>0)-(x<0);}typedef struct{int u,o,d,n,i,e;}F;
static F mf(void){F f={mpfr_underflow_p()!=0,mpfr_overflow_p()!=0,mpfr_divby0_p()!=0,mpfr_nanflag_p()!=0,mpfr_inexflag_p()!=0,mpfr_erangeflag_p()!=0};return f;}
static int fe(const ppf_context_t*c,F f){unsigned p=c->flags;return f.u==!!(p&PPF_FLAG_UNDERFLOW)&&f.o==!!(p&PPF_FLAG_OVERFLOW)&&f.d==!!(p&PPF_FLAG_DIVBY0)&&f.n==!!(p&PPF_FLAG_NAN)&&f.i==!!(p&PPF_FLAG_INEXACT)&&f.e==!!(p&PPF_FLAG_ERANGE);}
static int same(const ppf_t*p,mpfr_srcptr m){mpfr_t g;int ok;mpfr_init2(g,mpfr_get_prec(m));CHECK(ppf_get_mpfr(g,p,MPFR_RNDN)!=PPF_TERNARY_ERROR);if(mpfr_nan_p(m))ok=mpfr_nan_p(g);else if(mpfr_inf_p(m))ok=mpfr_inf_p(g)&&mpfr_signbit(m)==mpfr_signbit(g);else if(mpfr_zero_p(m))ok=mpfr_zero_p(g)&&mpfr_signbit(m)==mpfr_signbit(g);else ok=mpfr_equal_p(g,m);if(!ok)mpfr_printf(" got=%.*Rg ref=%.*Rg\n",80,g,80,m);mpfr_clear(g);return ok;}
static void setv(ppf_t*p,mpfr_ptr m,const char*s,ppf_context_t*c){CHECK(mpfr_set_str(m,s,0,MPFR_RNDN)==0);CHECK(ppf_set_mpfr(p,m,PPF_RNDN,c)!=PPF_TERNARY_ERROR);}
static void cu(const char*n,pfu pf,mfu rf,const char*v,unsigned ip,unsigned op){ppf_context_t c;ppf_t x,y;mpfr_t mx,my;ppf_context_init(&c);ppf_init2_ctx(&x,ip,&c);ppf_init2_ctx(&y,op,&c);mpfr_init2(mx,ip);mpfr_init2(my,op);setv(&x,mx,v,&c);for(int k=0;k<5;k++){ppf_context_flags_clear(&c,PPF_FLAGS_ALL);mpfr_clear_flags();int a=pf(&y,&x,pr[k],&c);int b=rf(my,mx,mr[k]);F f=mf();if(a==PPF_TERNARY_ERROR||!same(&y,my)||sg(a)!=sg(b)||!fe(&c,f)){fprintf(stderr,"U %s v=%s ip=%u op=%u r=%d a=%d b=%d pf=%x mf=%d%d%d%d%d%d\n",n,v,ip,op,k,a,b,c.flags,f.u,f.o,f.d,f.n,f.i,f.e);exit(2);}}ppf_clear(&x);ppf_clear(&y);ppf_context_clear(&c);mpfr_clear(mx);mpfr_clear(my);}
static void cuu(const char*n,pfuu pf,mfuu rf,const char*v,unsigned long u,unsigned ip,unsigned op){ppf_context_t c;ppf_t x,y;mpfr_t mx,my;ppf_context_init(&c);ppf_init2_ctx(&x,ip,&c);ppf_init2_ctx(&y,op,&c);mpfr_init2(mx,ip);mpfr_init2(my,op);setv(&x,mx,v,&c);for(int k=0;k<5;k++){ppf_context_flags_clear(&c,PPF_FLAGS_ALL);mpfr_clear_flags();int a=pf(&y,&x,u,pr[k],&c);int b=rf(my,mx,u,mr[k]);F f=mf();if(a==PPF_TERNARY_ERROR||!same(&y,my)||sg(a)!=sg(b)||!fe(&c,f)){fprintf(stderr,"UU %s v=%s u=%lu ip=%u op=%u r=%d a=%d b=%d pf=%x mf=%d%d%d%d%d%d\n",n,v,u,ip,op,k,a,b,c.flags,f.u,f.o,f.d,f.n,f.i,f.e);exit(3);}}ppf_clear(&x);ppf_clear(&y);ppf_context_clear(&c);mpfr_clear(mx);mpfr_clear(my);}
static void cb(const char*n,pfb pf,mfb rf,const char*av,const char*bv,unsigned ip,unsigned op){ppf_context_t c;ppf_t a,b,y;mpfr_t ma,mb,my;ppf_context_init(&c);ppf_init2_ctx(&a,ip,&c);ppf_init2_ctx(&b,ip,&c);ppf_init2_ctx(&y,op,&c);mpfr_init2(ma,ip);mpfr_init2(mb,ip);mpfr_init2(my,op);setv(&a,ma,av,&c);setv(&b,mb,bv,&c);for(int k=0;k<5;k++){ppf_context_flags_clear(&c,PPF_FLAGS_ALL);mpfr_clear_flags();int x=pf(&y,&a,&b,pr[k],&c);int z=rf(my,ma,mb,mr[k]);F f=mf();if(x==PPF_TERNARY_ERROR||!same(&y,my)||sg(x)!=sg(z)||!fe(&c,f)){fprintf(stderr,"B %s a=%s b=%s r=%d x=%d z=%d pf=%x mf=%d%d%d%d%d%d\n",n,av,bv,k,x,z,c.flags,f.u,f.o,f.d,f.n,f.i,f.e);exit(4);}}ppf_clear(&a);ppf_clear(&b);ppf_clear(&y);ppf_context_clear(&c);mpfr_clear(ma);mpfr_clear(mb);mpfr_clear(my);}
static void cbu(const char*n,pfbu pf,mfbu rf,const char*av,const char*bv,unsigned long u,unsigned ip,unsigned op){ppf_context_t c;ppf_t a,b,y;mpfr_t ma,mb,my;ppf_context_init(&c);ppf_init2_ctx(&a,ip,&c);ppf_init2_ctx(&b,ip,&c);ppf_init2_ctx(&y,op,&c);mpfr_init2(ma,ip);mpfr_init2(mb,ip);mpfr_init2(my,op);setv(&a,ma,av,&c);setv(&b,mb,bv,&c);for(int k=0;k<5;k++){ppf_context_flags_clear(&c,PPF_FLAGS_ALL);mpfr_clear_flags();int x=pf(&y,&a,&b,u,pr[k],&c);int z=rf(my,ma,mb,u,mr[k]);F f=mf();if(x==PPF_TERNARY_ERROR||!same(&y,my)||sg(x)!=sg(z)||!fe(&c,f)){fprintf(stderr,"BU %s a=%s b=%s u=%lu r=%d x=%d z=%d pf=%x mf=%d%d%d%d%d%d\n",n,av,bv,u,k,x,z,c.flags,f.u,f.o,f.d,f.n,f.i,f.e);exit(5);}}ppf_clear(&a);ppf_clear(&b);ppf_clear(&y);ppf_context_clear(&c);mpfr_clear(ma);mpfr_clear(mb);mpfr_clear(my);}
int main(void){unsigned p=53,ip=53;
const char *sp[]={"nan","inf","-inf","0","-0"};for(int i=0;i<5;i++){cu("sin",ppf_sin,mpfr_sin,sp[i],ip,p);cu("cos",ppf_cos,mpfr_cos,sp[i],ip,p);cu("tan",ppf_tan,mpfr_tan,sp[i],ip,p);cu("sinh",ppf_sinh,mpfr_sinh,sp[i],ip,p);cu("cosh",ppf_cosh,mpfr_cosh,sp[i],ip,p);cu("tanh",ppf_tanh,mpfr_tanh,sp[i],ip,p);cu("sech",ppf_sech,mpfr_sech,sp[i],ip,p);cu("asinh",ppf_asinh,mpfr_asinh,sp[i],ip,p);}
const char*grid[]={"-2","-1.5","-1","-0.5","0","0.5","1","1.5","2"};for(int i=0;i<9;i++){cu("sinpi",ppf_sinpi,mpfr_sinpi,grid[i],ip,p);cu("cospi",ppf_cospi,mpfr_cospi,grid[i],ip,p);cu("tanpi",ppf_tanpi,mpfr_tanpi,grid[i],ip,p);cuu("sinu",ppf_sinu,mpfr_sinu,grid[i],4,ip,p);cuu("cosu",ppf_cosu,mpfr_cosu,grid[i],4,ip,p);cuu("tanu",ppf_tanu,mpfr_tanu,grid[i],4,ip,p);}
const char*iv[]={"nan","inf","-inf","-2","-1","-0","0","1","2"};for(int i=0;i<9;i++){cu("asin",ppf_asin,mpfr_asin,iv[i],ip,p);cu("acos",ppf_acos,mpfr_acos,iv[i],ip,p);cu("atan",ppf_atan,mpfr_atan,iv[i],ip,p);cu("asinpi",ppf_asinpi,mpfr_asinpi,iv[i],ip,p);cu("acospi",ppf_acospi,mpfr_acospi,iv[i],ip,p);cu("atanpi",ppf_atanpi,mpfr_atanpi,iv[i],ip,p);cuu("asinu",ppf_asinu,mpfr_asinu,iv[i],8,ip,p);cuu("acosu",ppf_acosu,mpfr_acosu,iv[i],8,ip,p);cuu("atanu",ppf_atanu,mpfr_atanu,iv[i],8,ip,p);}
const char*ys[]={"0","-0","1","-1","inf","-inf"};const char*xs[]={"0","-0","1","-1","inf","-inf"};for(int i=0;i<6;i++)for(int j=0;j<6;j++){cb("atan2",ppf_atan2,mpfr_atan2,ys[i],xs[j],ip,p);cb("atan2pi",ppf_atan2pi,mpfr_atan2pi,ys[i],xs[j],ip,p);cbu("atan2u",ppf_atan2u,mpfr_atan2u,ys[i],xs[j],8,ip,p);}
const char*hh[]={"0","-0","inf","-inf","nan"};for(int i=0;i<5;i++){cu("csch",ppf_csch,mpfr_csch,hh[i],ip,p);cu("coth",ppf_coth,mpfr_coth,hh[i],ip,p);}
const char*ac[]={"nan","-inf","-2","0","0.5","1","inf"};for(int i=0;i<7;i++)cu("acosh",ppf_acosh,mpfr_acosh,ac[i],ip,p);
const char*at[]={"nan","-inf","-2","-1","-0","0","1","2","inf"};for(int i=0;i<9;i++)cu("atanh",ppf_atanh,mpfr_atanh,at[i],ip,p);
cuu("sinu_u0",ppf_sinu,mpfr_sinu,"0.5",0,ip,p);cuu("asinu_u0",ppf_asinu,mpfr_asinu,"-0.5",0,ip,p);cuu("acosu_u0",ppf_acosu,mpfr_acosu,"-0.5",0,ip,p);cuu("atanu_u0",ppf_atanu,mpfr_atanu,"-0.5",0,ip,p);
printf("OK specials\n");return 0;}
